import itertools

def solve_min_cost(n):
    m = n * (n - 1) // 2
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((i, j))

    min_total_cost = float('inf')

    for p in itertools.permutations(edges):
        d_min = [m + 1] * n
        d_max = [-1] * n
        for day, (u, v) in enumerate(p, 1):
            d_min[u] = min(d_min[u], day)
            d_max[u] = max(d_max[u], day)
            d_min[v] = min(d_min[v], day)
            d_max[v] = max(d_max[v], day)

        cost = sum(d_max[i] - d_min[i] + 1 for i in range(n))
        if cost < min_total_cost:
            min_total_cost = cost

    return min_total_cost

for n in range(2, 6):
    print(f"n={n}, cost={solve_min_cost(n)}")
